   bool gInsideNodeCanvas = false;
   ColorRequest gColor;
   ImVec4 gColorPickerRect(0, 0, 0, 0);
   CommentEditRequest gCommentEdit;
   // Screen-space rect of the last comment body drawn, so the dev test can aim
