         SpawnNode("Wavetable", "Synths", 40.0f, 40.0f);         // 0
         SpawnNode("Gain", "Synths", 320.0f, 40.0f);             // 1
         SpawnNode("Audio Out", "Utility", 600.0f, 40.0f); // 2

